// Render the one-page release candidate to a PDF with headless Chromium (Playwright).
// Usage: node admin/build/print_pdf.js v2/book/single.html v2/generation-z-developers-<version>.pdf
// Not part of the gate: the PDF is a convenience for printing, generated by the release that froze the candidate.
const path = require('path');
const fs = require('fs');
const ROOT = path.resolve(__dirname, '..', '..');
const [, , htmlRel, pdfRel] = process.argv;
if (!htmlRel || !pdfRel) { console.error('usage: node print_pdf.js <html> <pdf>'); process.exit(2); }
let chromium;
try { chromium = require('playwright').chromium; } catch (e) {
  try { chromium = require('/opt/node22/lib/node_modules/playwright').chromium; } catch (e2) { console.error('print_pdf: playwright is not installed; skipping the PDF'); process.exit(0); }
}
(async () => {
  const http = require('http');
  const serve = http.createServer((req, res) => {
    const p = path.join(ROOT, decodeURIComponent(req.url.split('?')[0]));
    if (!p.startsWith(ROOT) || !fs.existsSync(p) || fs.statSync(p).isDirectory()) { res.statusCode = 404; return res.end(); }
    const ext = path.extname(p);
    res.setHeader('content-type', { '.html': 'text/html; charset=utf-8', '.css': 'text/css', '.js': 'text/javascript', '.json': 'application/json', '.png': 'image/png', '.jpg': 'image/jpeg', '.svg': 'image/svg+xml' }[ext] || 'application/octet-stream');
    fs.createReadStream(p).pipe(res);
  });
  await new Promise(r => serve.listen(0, '127.0.0.1', r));
  const port = serve.address().port;
  const opts = fs.existsSync('/opt/pw-browsers/chromium') ? { executablePath: '/opt/pw-browsers/chromium' } : {};
  const browser = await chromium.launch(opts).catch(() => chromium.launch());
  const page = await browser.newPage();
  await page.goto(`http://127.0.0.1:${port}/${htmlRel}`, { waitUntil: 'networkidle' });
  await page.emulateMedia({ media: 'print' });
  await page.pdf({ path: path.join(ROOT, pdfRel), format: 'A4', printBackground: true, preferCSSPageSize: true,
    displayHeaderFooter: true, headerTemplate: '<span></span>',
    footerTemplate: '<div style="width:100%;font-size:8pt;color:#666;font-family:sans-serif;text-align:center;padding:0 20mm">Generation ZX Developers (GenAI Startup Edition), release candidate &middot; page <span class="pageNumber"></span> of <span class="totalPages"></span></div>' });
  await browser.close();
  serve.close();
  const kb = Math.round(fs.statSync(path.join(ROOT, pdfRel)).size / 1024);
  console.log(`print_pdf: wrote ${pdfRel} (${kb} KB)`);
})().catch(e => { console.error('print_pdf:', e.message); process.exit(1); });
